# analyze 3-structure connectivity
import numpy as np
from collections import deque
S = set(zip(*np.where(out==3)))
def nb8(p): 
    r,c=p
    for dr in(-1,0,1):
        for dc in(-1,0,1):
            if dr or dc: yield (r+dr,c+dc)
# connected comps of 3s (4-adj)
def comps(S, adj):
    seen=set(); cs=[]
    for p in S:
        if p in seen: continue
        q=deque([p]); seen.add(p); comp=[p]
        while q:
            x=q.popleft()
            for y in adj(x):
                if y in S and y not in seen: seen.add(y); q.append(y); comp.append(y)
        cs.append(comp)
    return cs
c4=comps(S,lambda p:[q for q in nb8(p) if abs(q[0]-p[0])+abs(q[1]-p[1])==1])
c8=comps(S,nb8)
print("4-comps",len(c4),[len(c) for c in c4])
print("8-comps",len(c8),[len(c) for c in c8])
# do 3s 8-adj touch all 2s?
twos=[tuple(map(int,t)) for t in twos]
for t in twos:
    print(t, any(q in S for q in nb8(t)))
print("3 seed adjacent:", [q for q in nb8((5,5)) if q in S])

# count 4-adj pairs among 3s
E=0
for (r,c) in S:
    for q in [(r+1,c),(r,c+1)]:
        if q in S: E+=1
print("edges",E,"nodes",len(S),"tree?" , E==len(S)-1)
# leaves count
deg={p:sum(q in S for q in [(p[0]+1,p[1]),(p[0]-1,p[1]),(p[0],p[1]+1),(p[0],p[1]-1)]) for p in S}
print("leaves", sum(1 for v in deg.values() if v==1), "deg counts", {k:sum(1 for v in deg.values() if v==k) for k in set(deg.values())})
# which points are in S-adjacency (points 8-adjacent to structure)? all 2s+3.
# Try: is it the minimum rectilinear steiner tree? hard. Check total length vs MST over points (manhattan MST length)
pts = twos+[(5,5)]
import itertools
def mst_len(pts):
    n=len(pts); import heapq
    seen={0}; h=[]; tot=0
    for j in range(1,n): heapq.heappush(h,(abs(pts[0][0]-pts[j][0])+abs(pts[0][1]-pts[j][1]),0,j))
    while len(seen)<n:
        d,i,j=heapq.heappop(h)
        if j in seen: continue
        seen.add(j); tot+=d
        for k in range(n):
            if k not in seen: heapq.heappush(h,(abs(pts[i][0]-pts[k][0])+abs(pts[i][1]-pts[k][1]),j,k))
    return tot
print("MST len", mst_len(pts), "3-count", len(S))

