def trace_path(S, start):
    path=[start]; prev=None; cur=start
    while True:
        nxts=[q for q in [(cur[0]+1,cur[1]),(cur[0]-1,cur[1]),(cur[0],cur[1]+1),(cur[0],cur[1]-1)] if q in S and q!=prev]
        if not nxts: break
        prev,cur=cur,nxts[0]; path.append(cur)
    return path
def runs(path):
    res=[]; 
    for i in range(1,len(path)):
        d=(path[i][0]-path[i-1][0], path[i][1]-path[i-1][1])
        if res and res[-1][0]==d: res[-1][1]+=1
        else: res.append([d,1])
    return res
